import ast, pathlib
wrappers = {"pc1_with_pcswitcher_mod","pc2_with_pcswitcher","pc2_without_pcswitcher_fn","pc2_with_old_pcswitcher_fn"}
for p in sorted(pathlib.Path("tests").rglob("*.py")):
    try:
        tree = ast.parse(p.read_text())
    except SyntaxError as e:
        print("SYNTAXERROR", p, e); continue
    for node in ast.walk(tree):
        if isinstance(node,(ast.FunctionDef, ast.AsyncFunctionDef)):
            args = {a.arg for a in node.args.args + node.args.kwonlyargs}
            w = args & wrappers
            direct = args & {"pc1_executor","pc2_executor"}
            if w and direct:
                print(f"{p}:{node.lineno} {node.name} -> wrappers={sorted(w)} direct={sorted(direct)}")
